def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]

    opp_c = 0
    for x in opp:
        if x == 'C':
            opp_c += 1
    opp_d = n - opp_c

    recent5 = opp[-5:] if n >= 5 else opp
    recent10 = opp[-10:] if n >= 10 else opp
    recent5_d = 0
    for x in recent5:
        if x == 'D':
            recent5_d += 1
    recent10_d = 0
    for x in recent10:
        if x == 'D':
            recent10_d += 1

    hostile = False
    if opp_c == 0:
        hostile = True
    elif n >= 3 and opp_c <= 1:
        hostile = True
    elif n >= 5 and recent5_d >= 4 and opp_c * 5 <= n * 2:
        hostile = True
    elif n >= 10 and recent10_d >= 7 and opp_c * 5 <= n * 3:
        hostile = True
    elif n >= 12 and opp_d * 3 >= n * 2:
        hostile = True

    total = 0
    punish = 0
    for i in range(n - 1):
        if me[i] == 'D':
            total += 1
            if opp[i + 1] == 'D':
                punish += 1

    exploit = False
    if not hostile and total > 0:
        if punish == 0 and opp_c * 10 >= n * 6:
            exploit = True
        elif total >= 4 and punish * 4 <= total and recent5_d <= 3:
            exploit = True
    if exploit and recent10_d >= 6:
        exploit = False

    if n == 1:
        if hostile:
            return 'D'
        return 'C'

    if n == 2:
        if opp_c == 2 and not hostile:
            return 'D'

    if exploit:
        if last_opp == 'C':
            return 'D'
        if last_opp == 'D':
            if total >= 2 and punish * 4 <= total:
                return 'D'
            return 'C'

    if last_opp == 'D':
        if hostile:
            return 'D'
        if n >= 2 and me[-2] == 'D':
            return 'C'
        if last_me == 'D':
            return 'C'
        if opp_c * 10 >= n * 8 and recent5_d <= 1:
            return 'C'
        return 'D'

    if last_me == 'D':
        return 'C'

    if not hostile and opp_c * 10 >= n * 9 and total >= 1 and punish >= 1:
        run_c = 0
        for x in reversed(opp):
            if x == 'C':
                run_c += 1
            else:
                break
        if run_c >= 6 and n >= 25 and rng.random() < 0.07:
            return 'D'

    return 'C'
